insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Чем отличается интерфейс от абстрактного класса и когда что выбирать в Java 17+?', 'Абстрактный класс — это наследование реализации: он может нести поля, конструкторы, состояние и защищённые методы, а класс наследует только один такой класс (single inheritance). Интерфейс — это контракт: только константы (public static final), default/static/private-методы с Java 8/9, но никакого экземплярного состояния. Практическое правило: интерфейс выбирают для определения способности/роли (Comparable, Supplier), абстрактный класс — когда есть общий скелет и состояние для целого семейства (AbstractList, шаблонный метод). С default-методами граница размылась, но состояние по-прежнему доступно только абстрактному классу. Класс, реализующий несколько интерфейсов с одинаковыми default-методами, обязан разрешить конфликт явно: InterfaceName.super.method(). В иерархиях библиотек норма — интерфейс + парный абстрактный скелет (List + AbstractList, InputStream и т.п.).', 'Что произойдёт при diamond-наследовании двух интерфейсов с одинаковым default-методом? Почему у интерфейса не может быть конструктора, но могут быть private-методы?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Optional: зачем нужен, почему не следует использовать его для полей и аргументов, и как правильно цепочкой обрабатывать?', 'Optional — это типизированный контейнер для «значения может не быть», заменяющий возвращение null и заставляющий вызывающего обработать пустоту явно. Правильная зона применения — только возвращаемый тип. Антипаттерны: Optional в полях (не сериализуется, лишняя обёртка), в аргументах (усложняет сигнатуру), Optional.get() без проверки (выбрасывает NoSuchElementException) и Optional.of на nullable (NPE сразу). Цепочка: map/flatMap трансформируют значение при наличии, orElse/orElseGet дают дефолт (orElse вычисляет выражение всегда — для дорогих операций только orElseGet), orElseThrow — исключение, ifPresent/isPresent — для совместимости. Пустой Optional.get вернёт исключение; для примитивов есть IntOptional-специализации. Антипаттерн «Optional из коллекции»: пустой List уже сам себе Optional — возвращайте пустую коллекцию. В Kotlin аналогичная ниша занята nullable-типами T? — язык решает проблему на уровне системы типов.', 'Чем orElse отличается от orElseGet по моменту вычисления и что это значит для вызова БД внутри? Почему Optional не реализует Serializable? Как Optional.flatMap связан с монадической композицией?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'synchronized и ReentrantLock: сравнение, когда оправдан явный lock, что такое fairness?', 'synchronized — блокировка уровня JVM: monitorhead, автоматическое освобождение, repeatable (reentrant), нельзя прервать ожидание, нет попытки захвата без ожидания. ReentrantLock — блокировка уровня JDK: tryLock() с таймаутом (не ждёт вечно, обходит deadlock), lockInterruptibly() (реагирует на interrupt), fairness-режим new ReentrantLock(true) — потоки получают захват в порядке FIFO-очереди (по умолчанию unfair — быстрее, но возможен starvation), и Condition — несколько условных переменных на один lock (await/signal вместо wait/notify). Явный lock требует ручной try/finally unlock — забытый unlock навсегда блокирует остальных. Практика: в 95% случаев хватает synchronized (компилятор и JIT оптимизируют через biased/thin locks), ReentrantLock берут для таймаутов, прерываемости, нескольких условий или сложной структуры. Для читателей-писателей — ReentrantReadWriteLock, а в Java 21 для простой блокировки стоит смотреть StampedLock (optimistic read) или synchronized по виртуальным потокам.', 'Почему unfair-режим по умолчанию быстрее? Как сделать таймаут на захват и что делать при неудаче? Чем Condition гибче wait/notify?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Пакет java.util.concurrent.atomic: CAS, ABA-проблема и LongAdder против AtomicLong — когда что?', 'Атомики (AtomicInteger, AtomicReference, ...) строятся на compare-and-swap — процессорной инструкции, атомарно сравнивающей ожидаемое значение и записывающей новое; CAS крутится в цикле до успеха (spinning, дешевле блокировки при низкой конкуренции). ABA-проблема: значение изменилось A->B->A, CAS считает его нетронутым; лечится AtomicStampedReference (пара значение+версия) или AtomicMarkableReference. Атомики дают также getAndIncrement, accumulate, lazySet/weakCompareAndSet (ослабленные барьеры памяти). AtomicLong — один счётчик: при 64 конкурирующих потоках все CAS-ятся в одну ячейку и конвейер деградирует (кэш-линия скачет между ядрами). LongAdder (подход Striped64) раскладывает счётчик в массив ячеек Cell[], каждый поток пишет в свою по probe-хешу, sum() суммирует — запись почти без конфликтов, но чтение не снапшотное. Правило: счётчики метрик под нагрузкой — LongAdder, точное значение и CAS-логика (ID-генератор, неблокирующий стек) — AtomicLong. Плюс помнить о false sharing: между hot-полями в очередь встают @Contended-поля (или ручной padding).', 'Почему у LongAdder.sum() нет согласованности с параллельными increment()? Как ABA ломает неблокирующий стек и чем помогает версия-штамп? Что такое false sharing и как @jdk.internal.vm.annotation.Contended его лечит?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие бывают сборщики мусора в HotSpot (Serial/Parallel/G1/ZGC) и как выбрать под latency vs throughput?', 'Serial — один поток STW, для контейнеров с сотней МБ и однопоточных нагрузок. Parallel — несколько потоков, цель throughput (пауза может быть длинной), хорош для батч-обработки. G1 (дефолт с Java 9) — регионный: куча бьётся на регионы, собирает в первую очередь регионы с максимумом мусора (garbage-first), использует SATB, справляется с падением фрагментации через evacuation; настраивается -XX:MaxGCPauseMillis — мягкая цель по паузе. ZGC/Shenandoah — конкурентные, почти без STW (паузы <1 мс независимо от размера кучи до 16 ТБ), используют цветные указатели/броки-барьеры; цена — чуть ниже throughput и выше расход на барьеры. Выбор: latency-sensitive сервис (API, торговля) — G1/ZGC, максимум операций в секунду без требований к паузе — Parallel, маленький контейнер — Serial. Метрики для решения: доля времени в GC, длина пауз (JFR/GC-лог), размер live-set. Частая ошибка — тюнинг GC до измерений: сначала профиль аллокаций.', 'Почему у G1 регионы и что такое SATB? Когда ZGC хуже G1 по throughput? Как по GC-логу понять, что пора менять коллектор?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JIT-компиляция в HotSpot: уровни C1/C2, инлайнинг, деоптимизация — как это влияет на бенчмарки?', 'Interpreter выполняет байткод сразу; через порог счётчика (−XX:CompileThreshold, счётчики горячести) метод компилируется. Tiered compilation (дефолт): C1 — быстрый компилятор с простыми оптимизаций (профилирует поведение), C2 — тяжёлый, использует профиль для спекулятивных оптимизаций: девиртуализация, escape analysis + скалярное замещение, разворот циклов, устранение проверок. Инлайнинг — фундамент всего: без него нет межпроцедурных оптимизаций; лимиты −XX:FreqInlineSize/MaxInlineSize, поэтому «миксометоды» без инлайна медленнее ожидаемого. Деоптимизация: если спекуляция C2 оказалась неверной (профиль был нерепрезентативен, класс-наследник приехал позже), метод откатывается в interpreter — это резкий провал производительности; отсюда обязательный прогрев бенчмарков (JMH: warmup iterations) — иначе меряете C1/interpreter. OSR (on-stack replacement) позволяет заменить цикл, уже крутящийся в interpreter. On-stack символы: flame-граф показывает скомпилированные фреймы; в JMH полезен -prof perfasm/gc, а «странная» производительность после рестарта — часто другой профиль прогрева.', 'Что такое escape analysis и когда скалярное замещение убивает аллокацию? Почему первый прогон бенчмарка всегда медленный и как JMH это решает? Что происходит при деоптимизации спекулятивного девиртуализированного вызова?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Stream API: ленивость, короткое замыкание и почему side-effects в forEach — плохо?', 'Конвейер Stream — декларативное описание обработки; промежуточные операции (filter, map, flatMap) ленивы и лишь собирают pipeline, терминальные (collect, forEach, count, anyMatch) запускают проход. Элемент проходит весь конвейер за один вертикальный проход — «колодец», а не поэтапные списки; короткозамыкающие операции (limit, findFirst, anyMatch) останавливают обработку при достижении результата, и бесконечный Stream.generate работает только с ними. Обязательное правило — нет side effects: lambda в filter/map должна быть чистой (stateless, не мутировать внешнее состояние) — нарушение (счётчик в map, добавление в общий список из forEach) ломается при параллельных стримах и делает код невекторизуемым; собирать результат нужно только через collect(Collectors.toList/toMap/groupingBy). Собственное сокращение — reduce/collect с ассоциативным аккумулятором. С stateful-лямбдами параллельный стрим даёт гонки и недетерминизм, а исключения в конвейере не caught — падение всего прохода. Для отладки — peek (только логирование, не менять данные).', 'Почему любойMatch по бесконечному стриму завершается, а collect — нет? Что случится с внешним ArrayList при parallel stream + forEach add? Какая операция stateful и почему filter с состоянием запрещён?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Parallel streams: на каком ForkJoinPool они работают и почему в веб-приложении это опасно?', 'parallelStream выполняет проход на общем ForkJoinPool.commonPool(), размером CPU-1; внутри он применяет work-stealing и split по характеристикам источника (хороший сплит у массивов/ArrayList, плохой у LinkedList/iterate). Опасности: (1) общий пул один на всё JVM — блокирующая операция внутри лямбды (JDBC-вызов, HTTP, lock) съедает воркеры и подвешивает чужие параллельные стримы и CompletableFutures без executor; (2) в контейнере с CPU-квотой 2 ядра пул крошечный, а параллелизм не ускоряет IO-bound задачи; (3) если commonPool исчерпан, работа выполняется в вызывающем потоке (ForkJoinPool[] workaround через submit на собственный пул: customPool.submit(() -> stream.parallel()...).get()). Правило: parallel стрим — только для CPU-bound, коротких, чистых лямбд на хорошо делимых источниках и большом N (тысячи+ элементов), иначе последовательный стрим или явный executor. Проверять не догмой, а измерением; для IO-параллелизма — CompletableFuture с собственным пулем или virtual threads.', 'Как выполнить параллельный стрим на собственном ForkJoinPool и зачем это делают? Почему parallelStream из 10 элементов почти всегда медленнее? Что случится при блокирующемся вызове в лямбде?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'null-безопасность Kotlin: ?., ?:, !!, lateinit, платформенные типы — разложите по местам.', 'Система типов разделяет T (не null) и T? — компилятор требует обработку null до использования. Операторы: безопасный вызов obj?.method() (null -> null), Элвис a ?: default, умный каст после проверки if (a != null), !! — бросить KotlinNullPointerException (код-смелл, допустим в тестах), let для выполнения только при наличии: a?.let{...}. Платформенные типы T! — типы из Java без аннотаций nullability: компилятор доверяет и не заставляет проверять, поэтому NPE приезжает в рантайме (карта get в Java возвращает T!); лечится аннотациями @Nullable/@NotNull в Java-коде или явной проверкой на границе. lateinit var — поле, которое будет проинициализировано позже (DI, тесты): доступ до инициализации даёт UninitializedPropertyAccessException; не работает с примитивами и nullable-типами, проверка isInitialized. lazy { } — потокобезопасная по умолчанию (SYNCHRONIZED) отложенная инициализация val. Антипаттерны: превращать всё в nullable «на всякий случай» и лепить !! по коду — дизайнируйте ненулевые типы в конструкторах и используйте sealed/Optional на границах.', 'Чем lateinit отличается от lazy и когда lateinit невозможен? Что такое платформенный тип и почему NPE из Java-вызова не ловится компилятором Kotlin? Почему !! считается код-смеллом?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Корутины: structured concurrency, suspend, Dispatchers — как не утекать работу и не блокировать потоки?', 'suspend-функция — функция с точками приостановки: компилятор превращает её в конечный автомат (CPS-преобразование), приостановка не блокирует поток — поток возвращается пулу, а возобновление планируется позже. Запуск в scope: launch (fire-and-forget Job), async (Deferred с результатом). Structured concurrency — ключевой принцип: каждый scope (coroutineScope, viewModelScope, runBlocking) ждёт своих детей и отменяет их при собственной отмене; утечка невозможна, если работа запускается в scope с ограниченным жизненным циклом, а не в GlobalScope (последний живёт вечно — антипаттерн). Dispatchers.Default (CPU-пул), IO (блокирующие вызовы: файлы, legacy JDBC,_blocking_ библиотеки), Main (UI), Unconfined (только тесты); withContext(Dispatchers.IO) переключает контекст для блокирующего куска. Отмена кооперативная: код обязан проверять isActive/вызывать suspend-функции (ensureActive, yield); блокирующий вызов внутри корутины без прерывания не отменится. Исключения: сбой ребёнка отменяет родителя (обычный scope) — чтобы изолировать, используют supervisorScope. Виртуальные потоки Java 21 закрывают ту же нишу на JVM-уровне без CPS.', 'Чем coroutineScope отличается от supervisorScope по распространению ошибок? Почему JDBC-вызов в корутине надо оборачивать в withContext(Dispatchers.IO)? Как работает кооперативная отмена и что сломает thread.sleep внутри suspend?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как работают proxy в Spring: JDK dynamic proxy против CGLIB, что ломает самопроксирование?', 'Spring реализует @Transactional/@Async/@Cacheable/AOP через обёртку над бином. JDK dynamic proxy — только для интерфейсов: прокси реализует интерфейс, вызовы делегируются InvocationHandler; бин, приведённый к классу, не скастуется (ClassCastException). CGLIB — подкласс бина: перехватывает не-final публичные методы; не работает с final-классами/методами и требует конструктор без аргументов (с Spring 4+ objenesis). Дефолт Spring Boot — CGLIB (proxyTargetClass=true). Ограничения: (1) самовызов this.method() не проходит через прокси — аннотация не сработает, лечится self-injection, AopContext.currentProxy() или разносом по бинам; (2) private/final методы не перехватываются; (3) внутренние вызовы @Configuration (lite mode) тоже без прокси. mode=''aspectj'' (织 weave) снимает ограничения, но требует агент — почти не используют. Диагностика: toString/класс бина показывает $$EnhancerBySpringCGLIB или $Proxy; AopUtils.isAopProxy, AopUtils.isCglibProxy.', 'Почему this.someTransactionalMethod() не открывает транзакцию и три способа починить? Когда обязателен CGLIB? Что не так с final-методом в CGLIB-прокси?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Жизненный цикл бина в Spring: от BeanDefinition до destruction, где вплетаются proxy и @PostConstruct?', 'Цикл: регистрация BeanDefinition -> BeanFactoryPostProcessor (в т.ч. PropertySourcesPlaceholderConfigurer, ConfigurationClassPostProcessor сканирует @Configuration) -> instantiate (конструктор, косметика cglib-конфигураций) -> populate (внедрение зависимостей: field/setter/конструктор) -> Aware-интерфейсы (BeanNameAware, ApplicationContextAware) -> BeanPostProcessor.postProcessBeforeInitialization -> @PostConstruct (InitDestroyAnnotationBeanPostProcessor) -> InitializingBean.afterPropertiesSet / init-method -> BeanPostProcessor.postProcessAfterInitialization — именно здесь AnnotationAwareAspectJAutoProxyCreator оборачивает бин в AOP-прокси -> бин готов -> контекст отдан (ContextRefreshedEvent) -> на shutdown: @PreDestroy -> DisposableBean.destroy / destroy-method. Отсюда практические следствия: @Autowired-поля недоступны в конструкторе (поля внедряются после) — использовать конструкторную инъекцию; proxy виден всем, кто получает зависимость после postProcess, но не this внутри; @PostConstruct выполняется до проксирования — @Transactional внутри него не сработает; круговые зависимости с прокси частично лечатся三级 exposure (early reference), но с Spring Boot 2.6 дефолтно запрещены — правильнее перепроектировать или @Lazy.', 'Почему в конструкторе бина ещё не injected поля и как конструкторная инъекция это решает? Где именно в цикле вешается @Transactional-прокси и почему это важно для @PostConstruct? Как Spring разрешает циклические зависимости и почему Boot их запретил?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'N+1 проблема: как обнаружить, как лечить (JOIN FETCH, EntityGraph, batch)?', 'N+1 — при выборке N родительских сущностей ленивая коллекция каждого родителя грузится отдельным запросом: 1 запрос за списком + N за детей. Обнаружение: лог SQL (hibernate.show_sql/ datasource-proxy/ p6spy), статистика SessionFactory (open-in-view выключить, чтобы видеть всё), визуально — сотни одинаковых select после одного списка. Лечение: (1) JOIN FETCH в JPQL: select o from Order o join fetch o.items — одним запросом, осторожно с двумя и больше fetch-коллекциями (MultipleBagFetchException / декартово произведение); (2) @EntityGraph(attributePaths=...) на репозиторий — то же без JPQL; (3) @BatchSize(size=50)/ hibernate.default_batch_fetch_size — вместо N запросов делает N/50 с IN(...); (4) проекции DTO (constructor expression, interface projection) — не тянут сущности вовсе; (5) кэш запросов. Профилактика: LAZY по умолчанию для всех ассоциаций, fetch только точечно на сценарий, OSIV отключён (spring.jpa.open-in-view=false), отчёты — на проекциях.', 'Почему два join fetch на коллекции падают с MultipleBagFetchException и как обойти (Set, два запроса)? Что делает default_batch_fetch_size? Чем DTO-проекция лучше EntityGraph для отчёта?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Пессимистичные и оптимистичные блокировки в JPA: @Version, PESSIMISTIC_LOCKING, lost update?', 'Lost update — две транзакции читают одну строку, обе пишут, вторая затирает первую. Оптимистичная стратегия: поле @Version (число/таймстамп), при UPDATE в WHERE подставляется версия; чья-то версия не совпала — OptimisticLockException, транзакция откатывается, повторить бизнес-логику (retry с backoff). Подходит при редких конфликтах (пользовательские формы). Пессимистичная: SELECT ... FOR UPDATE / FOR SHARE (LockModeType.PESSIMISTIC_WRITE/READ) — БД блокирует строку до конца транзакции; конфликт выстраивается в очередь вместо отката. Подходит для горячих счётчиков/секций и коротких транзакций; риск — deadlock при разном порядке блокировок и деградация throughput при длинных транзакциях. В Spring: @Lock(LockModeType.PESSIMISTIC_WRITE) на метод репозитория, @Transactional обязателен. Важно: OptimisticLockException наружу может вылезти как wrapper (ObjectOptimisticLockingFailureException) — ловить и ретраить на уровне сервиса. Для «check-then-act» между запросами (прочитал в HTTP-запросе, записал в другом) версия — единственная честная защита без длинных транзакций.', 'Почему без @Version Hibernate не видит потерянный апдейт? Как ретраить OptimisticLockException и где нельзя слепо повторять транзакцию? Чем FOR UPDATE отличается от FOR SHARE и когда возникает deadlock?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Архитектура Spring Security: SecurityFilterChain, AuthenticationManager, контекст — как течёт запрос?', 'Запуск: DelegatingFilterProxy (мост servlet->Spring) -> FilterChainProxy (SecurityFilterChain по матчерам) -> цепочка фильтров по порядку: DisableEncodeUrlFilter -> ... -> CsrfFilter -> UsernamePasswordAuthenticationFilter -> ... -> ExceptionTranslationFilter -> AuthorizationFilter (последний, решает доступ) -> контроллер. Аутентификация: фильтр собирает токен (UsernamePasswordAuthenticationToken) -> AuthenticationManager (обычно ProviderManager) опрашивает AuthenticationProvider''ы; провайдер использует UserDetailsService (логин->UserDetails) и PasswordEncoder; результат — Authentication с principal/authorities -> кладётся в SecurityContextHolder (по умолчанию ThreadLocal) -> AuthorizationFilter сверяет authorities с правилами. Контекст распространяется: SecurityContextHolder.MODE_INHERITABLEThreadLocal для пулов, в реактиве — Reactor context. Выход из системы — LogoutFilter, cleanup контекста. Кастомизация: свои фильтры addFilterBefore/After, свои провайдеры, @EnableMethodSecurity для @PreAuthorize на методах. JWT-сценарий: OncePerRequestFilter парсит токен, сам кладёт Authentication в контекст — без AuthenticationManager.', 'Зачем ExceptionTranslationFilter стоит до AuthorizationFilter и что он ловит? Как работает ThreadLocal-контекст в асинхронных сервлетах/пулах? Как встроить JWT-фильтр и почему он OncePerRequestFilter?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'CSRF: механика атаки, почему токен в куке не спасает, SameSite и как защищаться в SPA+API?', 'CSRF использует авторизованную сессию жертвы: браузер сам прикладывает куки к запросу на другой сайт (img/form/fetch без CORS). Классическая защита — synchronizer token: сервер выдаёт per-session CSRF-токен, тот должен прийти в header/form, чужой сайт его прочитать не может (same-origin policy). Токен в куке бессмысленен — кука и так прикладывается автоматически. Double-submit: случайный токен и в куке, и в заголовке — сервер сверяет равенство (не требует состояния). Современно: SameSite-атрибут кук (Lax по умолчанию в Chrome: кросс-сайтовые POST не получают куку) — сильный слой, но не полный (старые браузеры, Lax+GET-навигации). Для stateless JWT в Authorization-заголовке CSRF не страшен вовсе — заголовок скрипт чужого домена поставить не может (без CORS-разрешения). SPA+API: либо токен в заголовке + без кук, либо кука + CSRF-токен из responseBody/куки XSRF-TOKEN, читаемой JS (Spring Security так и делает для Angular/React из коробки), плюс SameSite=Lax/Strict и CORS с whitelist-источников. Отключать CsrfFilter «потому что API» можно только если действительно нет cookie-аутентификации.', 'Почему SameSite=Lax не является полной заменой CSRF-токену? Чем double-submit отличается от synchronizer token? В каком случае stateless JWT полностью снимает CSRF-риск?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Content negotiation и преобразование тел в Spring MVC: как запрос JSON становится объектом и обратно?', 'DispatcherServlet подбирает HttpMessageConverter по типу контента и классу целевого объекта: @RequestBody -> AbstractJackson2HttpMessageConverter (JSON через ObjectMapper), для XML — JAXB/Marshalling, для бинарных — ByteArray/Resource. Выбор формата: заголовок Accept (и Content-Type на запрос), суффикс пути и параметр format (устаревшие стратегии). Кастомизация ObjectMapper бином Jackson2ObjectMapperBuilder (даты, null-обработка, naming strategy), @JsonView для разных проекций одного DTO, @JsonIgnoreProperties на границах. Ошибки: HttpMediaTypeNotAcceptableException (нет конвертера под Accept), HttpMessageNotReadableException (битый JSON -> 400 через DefaultHandlerExceptionResolver). Загрузка файлов — MultipartResolver (стандартный servlet part), стриминг больших тел — InputStream/Resource + StreamingResponseBody. Для WebClient/Feign симметрично работают Encoder/Decoder. В REST-контроллерах ResponseEntity даёт контроль статусов/заголовков, ProblemDetail (RFC 7807) — стандартный формат ошибок в Spring 6.', 'Как добавить глобальную кастомизацию Jackson (даты ISO, не писать null)? Что вернёт сервер при Accept: application/xml без JAXB-конвертера? Как организовать выгрузку большого файла без буферизации в память?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', ' propagation уровни @Transactional: REQUIRED, REQUIRES_NEW, NESTED — различия и типовые ловушки?', 'REQUIRED (дефолт): при существующей транзакции присоединяется, иначе создаёт новую — внутренний вызов участвует в той же физической транзакции, rollback-only помечает всю внешнюю (UnexpectedRollbackException на коммите внешней). REQUIRES_NEW: всегда своя физическая транзакция — внешняя подвисает (соединение удерживается!), внутренняя коммитится независимо; используют для аудита/логов, которые обязаны сохраниться даже при откате основной; ловушки — пул соединений истощается при вложенности, deadlock с внешней транзакцией по тем же строкам. NESTED: savepoint внутри текущей транзакции — откат внутренней до savepoint не трогает внешнюю, но итоговый коммит один (JDBC savepoint, не поддерживается некоторыми БД/JPA-провайдерами вне Hibernate). Ещё: SUPPORTS/MANDATORY/NEVER/NOT_SUPPORTED — управление наличием. Общие грабли: private/final методы, самовызов this.m(), не-public классы, Exception: по умолчанию откат только на RuntimeException/Error — checked нужно rollbackFor; REQUIRES_NEW обязателен в отдельном бине или через self-proxy.', 'Почему после REQUIRES_NEW-вставки аудит остаётся даже при откате внешней транзакции? Что такое rollback-only и откуда UnexpectedRollbackException? Когда NESTED выгоднее REQUIRES_NEW?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Service discovery и балансировка в микросервисах: Eureka/Consul, client- vs server-side LB?', 'Service discovery решает проблему «по какому адресу жить инстанс, который плавает в k8s/autoscaling»: реестр (Eureka, Consul, etcd+Kubernetes DNS) хранит живые инстансы, здоровье — через heartbeat/health-check (TTL или TCP/HTTP probe), мёртвые выпадают. Client-side load balancing: потребитель сам получает список инстансов и выбирает (Spring Cloud LoadBalancer; Ribbon в прошлом) — меньше сетевых хопов, тонкие политики (zone-aware), но клиент несёт логику и нужен стек на каждом языке. Server-side: балансировщик перед сервисами (nginx, Envoy, AWS ALB) — клиент прост, но добавляется хоп и точка отказа. В Kubernetes внутренняя служба = ClusterIP + kube-proxy (iptables/IPVS), где LB уже встроен, а discovery — DNS: сервис-клиенты просто зовут http://payments. Практика: связка k8s-Service + readinessProbe (наготове только прогретые), для гетерогенных сред — Consul/Eureka + Spring Cloud LB; circuit breaker (Resilience4j) — на стороне клиента отмерших/долгих инстансов.', 'Чем readinessProbe отличается от livenessProbe с точки зрения discovery? Почему в k8s Eureka обычно не нужна? Кто должен обеспечивать retry: LB, istio или приложение?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Распределённые транзакции: saga, outbox, 2PC — когда какой паттерн оправдан?', '2PC (two-phase commit) — координатор готовит участников (prepare: фиксируют намерение) и потом командует commit/abort; даёт атомарность, но блокирует ресурсы на время фазы, требует XA-драйверов, единый координатор — точка отказа; в высоконкурентных веб-системах почти не применяют. Saga — последовательность локальных транзакций, каждый шаг публикует событие, триггерящее следующий; отказ компенсируется обратными операциями (compensating transactions: отменить бронь, вернуть деньги). Оркестрация (центральный менеджер состояний) vs хореография (сервисы реагируют на события) — первую проще отлаживать, вторую проще расширять. Ключевая инфраструктура — transactional outbox: бизнес-запись и событие в одну локальную транзакцию в outbox-таблицу, отдельный relay (Debezium/CDC или poller) публикует в Kafka — решает dual-write (коммит БД + публикация, одно без другого). Идемпотентность потребителей обязательна (dedup по ключу события), плюс correlation-id для трассировки saga. Вывод: там, где допустима eventual consistency (заказы, платежи) — saga+outbox; строгая атомарность в одной БД — обычная локальная транзакция, сервисы режут так, чтобы она была возможна.', 'Что такое dual-write problem и как именно outbox её закрывает? Чем оркестрируемая сага отличается от хореографии и что проще откатывать? Почему идемпотентный потребитель обязателен?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Consumer group и rebalance в Kafka: как распределяются партиции, что ломает долгий rebalance?', 'Партиции топика распределяются между членами consumer group: каждая партиция закреплена ровно за одним консьюмером группы (group coordinator + Assignor: range/roundrobin/sticky/cooperative-sticky). Rebalance происходит при изменении состава группы (упал/пришёл консьюмер, изменение подписки) и переносит партиции; до KIP-429 ( cooperative rebalance) это stop-the-world: все консьюмеры отдают партиции, коммиты подвисают; cooperative-sticky переносит только изменённую долю. Долгий rebalance вызывает: max.poll.interval.ms превышен (консьюмер не успел обработать батч — его исключают, а он вернётся — шторм), session.timeout.ms слишком большой, тяжёлая инициализация в rebalanceListener, невозвращающийся joinGroup. Настройки: session.timeout.ms ~10-45с, heartbeat.interval.ms = 1/3, max.poll.interval.ms по времени обработки батча, max.poll.records уменьшить. Коммит смещений: auto-commit по времени (риск двойной обработки и потери при падении между fetch и commit) vs enable.auto.commit=false + commitSync/commitAsync после обработки; exactly-once на стороне потребителя достигается только идемпотентной обработкой + хранением offset вместе с результатом (транзакционный консьюмер read-process-write).', 'Почему при остановке консьюмера партиции переезжают и как cooperative-sticky уменьшает даунтайм? Что происходит при превышении max.poll.interval.ms и как это лечится? Чем опасен auto-commit при падении после обработки, но до коммита?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Гарантии доставки в Kafka: acks, idempotent producer, транзакции — как собрать exactly-once?', 'acks=0 — пожарил и забыл (потери при падении лидера), acks=1 — лидер записал (потеря при падении до репликации), acks=all — записали все ISR (min.insync.replicas>=2), максимальная durability.Producer может дублировать при ретрае таймаута — enable.idempotence=true (дефолт в новых клиентах): брокер дедуплицирует по PID+sequence number в пределах партиции. Это даёт exactly-once в пределах одного producer->partition. Транзакции (Kafka 0.11+): producer с transactional.id пишет атомарно в несколько партиций + отправляет смещения (sendOffsetsToTransaction) — консьюмер с isolation.level=read_committed видит только закоммиченное; реализует паттерн consume-transform-produce exactly-once (Kafka Streams пользуется этим из коробки через EOS). Ограничения: end-to-end exactly-once до внешних систем (БД) не распространяется — там outbox/идемпотентность. Ещё на доставку влияют: retries + delivery.timeout.ms, compression, linger.ms/batch.size (throughput vs latency), replication factor=3, unclean.leader.election=false (не допускать отставшую реплику в лидеры — жертва availability ради консистентности).', 'Что даёт idempotent producer и почему без него ретраи дублируют? Как sendOffsetsToTransaction закрывает consume-transform-produce? Почему exactly-once не действует до внешней БД и что делают на стыке?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Индексы PostgreSQL: B-tree, частичные, составные — как читает EXPLAIN и когда индекс не используется?', 'Дефолтный B-tree обслуживает =, <, >, BETWEEN, LIKE ''префикс%'', ORDER BY (даёт уже сортированные данные) и уникальные ограничения; составной индекс (a,b) работает по префиксу — фильтр по b без a не использует, зато покрывающий (covering, INCLUDE) закрывает Index Only Scan (при актуальном visibility map). Частичный (partial) — WHERE status=''pending'' — маленький и горячий срез. GIN — инвертированный: jsonb, массивы, full-text; GiST — геометрия/kNN; BRIN — гигантские таблицы с естественной корреляцией (время), крошечный по размеру. EXPLAIN (ANALYZE, BUFFERS): Seq Scan против Index Scan/Index Only Scan, rows-оценка против факта (большой промах — статистика: ANALYZE, default_statistics_target), cost/actual time. Индекс не используется: маленькая таблица, селективность низкая (30% строк — дешевле seq scan), статистика устарела, тип выражения не совпадает (col::text), LIKE с ведущим %, OR по разным колонкам (bitmap OR спасает частично), коллиция/иммутабельность функции мешает. Лечение: составные/частичные индексы под конкретные запросы, статистика, устранение приведений типов; проверять не догадкой, а EXPLAIN ANALYZE на продуктивных данных.', 'Почему по составному индексу (a,b) запрос только по b не индексируется? Когда Index Only Scan деградирует до обычного Index Scan? Что делает Bitmap Heap Scan и когда он выгоднее простого Index Scan?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Уровни изоляции и многоверсионность PostgreSQL: как MVCC хранит версии, откуда bloat и что делает vacuum?', 'MVCC: UPDATE = вставка новой версии кортежа + отметка xmax у старой; DELETE помечает xmax. Читатель по своей транзакции выбирает, какая версия видима (snapshot: xmin <= xmax criteria, CLOG-биты). Отсюда читатели не блокируют писателей и наоборот; Read Committed (дефолт) перечитывает снапшот на каждый оператор — nonrepeatable read и phantom возможны; Repeatable Read в PG — snapshot на транзакцию (аномалии записи: serialization failure при конфликте); Serializable — SSI, предикатные блокировки, откат при аномалии (retry обязателен). Мёртвые версии (dead tuples) не возвращаются в место автоматически — таблица пухнет (bloat), индексы тоже. Autovacuum: собирает мёртвые кортежы (после horizon старейшей транзакции), обновляет visibility map (основание Index Only Scan и autovacuum-frozen), freeze старых кортежей (anti-wraparound; XID 32-битный, wraparound защита). Практика: длинные транзакции/слоты репликации/abandoned prepared держат horizon — bloat растёт; мониторинг pg_stat_user_tables (n_dead_tup), last_autovacuum; тяжёлые случаи — pg_repack онлайн без блокировок. Для конкурентных апдейтов одной строки — SELECT FOR UPDATE / оптимистичная версия в приложении.', 'Чем Repeatable Read в PostgreSQL отличается от стандарта SQL и почему phantom там невозможен? Что удерживает dead tuples от vacuum (долгая транзакция, слот репликации)? Почему XID wraparound требует freeze?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Redis как кэш и rate limiter: TTL, инвалидация, атомарность через Lua — базовые паттерны?', 'Кэш-aside: приложение читает Redis, промах — из БД и запись с TTL; TTL обязателен (без него кэш протухает навсегда), jitter на TTL размазывает expiry-шторм. Инвалидация: по событию (обновил сущность — удалил ключ DEL) или по версии ключа; cache stampede (пролой + все бьют БД) лечат блокировкой на первый промах (SET NX + короткий TTL лок-ключа) или логическим expiry. Отсутствие задачи в кэше ≠ отсутствие в БД: кэшировать и негативные результаты (null с коротким TTL). Rate limiter: fixed window (INCR + EXPIRE) — прост, но рывок на границе окон; token bucket/sliding window на Lua-скрипте: атомарно прочитать-посчитать-записать (Redis выполняет Lua атомарно, без гонок); распределённый лимит по ключу user:ip. Hot key — shard его имени; big key (список на миллион) — резать. Spring: RedisTemplate/StringRedisTemplate, @Cacheable с RedisCacheManager (serialization — JSON, не JDK-сериализацию). Персистентность для кэша не критична (maxmemory allkeys-lru), для rate-лимитера потеря = сброс лимитов — учесть AOF.', 'Почему rate limiter на INCR+EXPIRE даёт двойной лимит на границе окон и как это чинит Lua-скрипт? Что такое cache stampede и логическое expiration? Каким政治 eviction-политикам верить для кэша против очередей?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Моделирование данных в MongoDB: embed vs reference, как выбор влияет на запросы?', 'Embed (вложенный документ/массив) — данные читаются одним документом, атомарный апдейт всего агрегата; хорош для «принадлежит и читается вместе» (комментарии поста, адреса клиента). Reference — отдельная коллекция по id; хорош для shared-данных (пользователь в тысячах заказов), больших вложений (лимит 16 МБ на документ) и независимой жизненным циклом. Антипаттерны: неограниченный рост массива (unbounded array) — листинг тормозит, document shift; massive arrays -> вынести в отдельную коллекцию с bucketing (по 100 элементов). Схема строится под паттерны доступа (query-first design): какие запросы частые — под них embed и индекс; редкие джойны — $lookup (медленнее SQL-join, лучше денормализовать копию поля). Транзакции в 4.0+ есть (multi-document на replica set), но дороги — правильное моделирование должно их избегать. Индексы как в реляционной БД: по полям фильтра/сортировки, compound-порядок ESR (Equality-Sort-Range), covered queries через projection. Агрегационный pipeline ($match -> $group -> $project) заменяет SQL-отчёты, $merge для materialized view.', 'Когда unbounded array надо выносить из документа и что такое bucketing? Почему $lookup считается антипаттерном в hot-path? Как порядок полей compound-индекса (ESR) влияет на план?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kubernetes Deployment, ReplicaSet, Pod — как происходит rolling update и rollback?', 'Pod — единица запуска (один или несколько контейнеров с общими network/storage, ephemeral по природе). ReplicaSet следит за количеством реплик по label selector. Deployment управляет ReplicaSet''ами: при изменении pod template создаётся НОВЫЙ ReplicaSet, старый масштабируется вниз — rolling update: maxSurge (сколько сверх реплик поднимать) и maxUnavailable (сколько может отсутствовать) регулируют скорость/доступность; ReadinessProbe гарантирует, что в Service попадают только готовые поды. Откат: kubectl rollout undo — Deployment просто масштабирует прошлый ReplicaSet обратно (история revisionHistoryLimit). Прерывание обновления — ProgressDeadlineExceeded. Стратегия Recreate (сначала убить всех) — когда два экземпляра несовместимы. Probe: liveness (перезапуск упавшего), readiness (вывод из балансировки), startup (медленно стартующие: ожидание перед остальными). Для stateful — StatefulSet (стабильные имена, ordinal), для daemon — DaemonSet, cron — CronJob.', 'Зачем нужны maxSurge/maxUnavailable и что даст 25%/0? Как readinessProbe предотвращает попадание непрогретого пода в Service? Чем StatefulSet отличается от Deployment?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Ресурсы и QoS в Kubernetes: requests/limits, CPU throttling, OOMKilled — как диагностировать?', 'requests — гарантия планировщика (scheduler бинает под на node, где хватает CPU request/memory request), limits — потолок. CPU limit реализован CFS-квотой: контейнер, упершийся в лимит, троттлится (latency растёт, cfs_throttled в /sys/fs/cgroup) — не убийство, а замедление; поэтому latency-чувствительные сервисы часто держат requests=limits или вовсе без CPU limit. Memory limit — жёсткий: превышение -> OOMKilled (exit 137, restart) — cgroup OOM killer убивает процесс. QoS-класс из пропорций: Guaranteed (requests=limits на всё) — последними на выселение; Burstable — по превышению request против использования; BestEffort — первые жертвы при нехватке памяти на узле (eviction по order: BestEffort -> Burstable превысившие request -> Guaranteed). Диагностика: kubectl describe pod (last state OOMKilled, restarts), metrics-server/kubectl top, throttling в cAdvisor/Prometheus (container_cpu_cfs_throttled_periods), у пода в events — eviction reasons. Практика: memory requests=limits (предсказуемость), CPU request по реальному profile, limits по容量 узла; HPA масштабирует по CPU/memory utilization относительно requests.', 'Почему CPU limit редко ставят на latency-сервисы и что при этом с noise neighbors? Что означает exit code 137 и чем OOMKilled отличается от eviction? Как класс QoS влияет на порядок выселения при нехватке памяти?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Тестовая пирамида для Spring Boot: unit/slice/@SpringBootTest/Testcontainers — что где проверять?', 'Юнит-тесты (JUnit + Mockito, без Spring) — чистая логика: сервисы с замоканными зависимостями, мапперы, утилиты; быстрые сотни штук. Slice-тесты: @WebMvcTest поднимает только web-слой (контроллеры + фильтры + MockMvc, сервисы — @MockBean), @DataJpaTest — только JPA (embedded H2 по умолчанию или Testcontainers через @AutoConfigureTestDatabase(replace=NONE)), @JsonTest — сериализация; они ловят связку аннотаций без полного контекста. @SpringBootTest — весь контекст; с MOCK веб-окружением + MockMvc или RANDOM_PORT + TestRestTemplate/WebTestClient; медленные — держать немного (интеграционные сценарии). Testcontainers — реальный PostgreSQL/Kafka в Docker: @ServiceConnection (Boot 3.1+) создаёт datasource автоматически; гонять миграции Flyway против живой БД — ловит несовместимости схемы. Архитектура пирамиды: много юнитов, средне slice, мало полноценных интеграционных; E2E (отдельный стенд/SELENIUM) — только критические пути. Контекст кэшируется между тестами одного конфига — избегать @DirtiesContext и лишних профилей, иначе пересоздание съест минуты CI.', 'Чем @WebMvcTest отличается от @SpringBootTest + MockMvc по стоимости? Зачем Testcontainers вместо H2 и какие баги он ловит? Почему @DirtiesContext вредит скорости всего набора?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Три столпа наблюдаемости и золотые сигналы: что мерить в сервисе на Spring Boot?', 'Логи, метрики, трейсы — три источника истины; корреляция через trace_id (MDC + W3C traceparent). Метрики — Micrometer (фасад) -> Prometheus (pull, exposition /actuator/prometheus): счётчики (counter — только рост), gauges (мгновенное значение), histogram/summary (распределения: p95/p99 latency, апдейтительность через histogram_buckets). Золотые сигналы Google SRE: latency (p50/p95/p99 отдельно по эндпоинтам, ошибки считать отдельно — иначе хвост смешается), traffic (rps), errors (rate по статусам/типам), saturation (пулы: connection pool, thread pool, GC, CPU/mem, глубина очереди). Автоматика Spring Boot: http.server.requests (по URI/статусу/исключению), hikaricp, jvm.*, system.*; свои — Counter/Timer/Gauge через MeterRegistry, @Timed. Алертинг по симптомам (slo burn rate), не по причинам; дашборды — service-level + resource-level. Трейсы: Micrometer Tracing (бывший Sleuth) + OTLP -> Tempo/Jaeger: span на HTTP/DB/Kafka, ищем медленные цепочки. RED (rate-errors-duration) для сервисов, USE (utilization-saturation-errors) для ресурсов.', 'Почему latency ошибочных запросов надо считать отдельно от успешных? Чем histogram отличается от summary и что позволяет aggregation по datacenter? Что такое burn rate в алертах по SLO?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Flyway в проекте: зачем, какversioned/undo/repeatable миграции различаются и как безопасно менять схему под нагрузкой?', 'Flyway ведёт журнал схемой: versioned-миграции V<n>__desc.sql применяются один раз в порядке версий (таблица flyway_schema_history, checksum — изменение применённого файла ломает validate). Repeatable (R__desc.sql) выполняются заново при изменении checksum — представления/функции. Undo — платная версия, откат пишется вручную. Правила безопасной эволюции: совместимые с старым кодом изменения (expand-contract): сначала добавить колонку/таблицу, развернуть код, потом удалять старое; NOT NULL добавлять в три шага (nullable -> backfill батчами -> set not null), длинные ALTER на PostgreSQL (пересоздание таблицы, lock) — в максимальную эксплуатационную паузу или через的工具 типа pt-online-schema-change; индекс — CREATE INDEX CONCURRENTLY (без блокировки записи, вне транзакции — Flyway помечает такие миграции отдельно). В CI: миграции накатываются на чистую БД (Testcontainers) — падение ловится до прода; в рантайте spring.flyway.enabled=true до старта JPA-валидации. Hot-фикс на проде руками + запись в истории = конфликт: лучше всегда через миграцию.', 'Почему нельзя редактировать уже применённую миграцию и что такое checksum mismatch? Какие три шага у безопасного добавления NOT NULL колонки? Что даёт CREATE INDEX CONCURRENTLY и в чём его подвох для Flyway?' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Пайплайн CI/CD для Spring Boot + Next.js: какие стадии и гейты качества обязательны?', 'Минимальный надёжный конвейер: (1) checkout + кэш зависимостей (Gradle/npm cache по lock-файлу — экономит минуты); (2) статика: compile + detekt/ktlint, eslint/tsc --noEmit; (3) тесты: unit + integration (Testcontainers требует docker; параллелизация Gradle --max-workers, Matrix-джобы по модулям); (4) сборка артефактов: bootJar + docker build (multi-stage: сборочный образ -> runtime-слой без gradle/node, slim base); (5) гейты качества: покрытие (JaCoCo report + порог), scan уязвимостей (Trivy/grype по образу, dependency-check / dependabot вне пайпа); (6) deploy: staging автоматически из develop, prod — по тегу/ручному approval; (7) smoke-тест после деплоя (/actuator/health, ключевой сценарий). Гейты обязательны красным: падение теста/скана блокирует merge (branch protection), а не «разберёмся потом». Артефакт неизменяем: тот же образ проходит staging и prod (никакой пересборки на проде). Секреты — из vault/GitHub Environments, не в коде; версии — семвер через теги. Откат = redeploy прошлого образа, поэтому деплой должен быть идемпотентным (helm/k8s rollout undo).', 'Почему артефакт, прошедший staging, нельзя пересобирать для прода? Какие гейты должны быть красными блокерами merge? Как организовать откат деплоя за минуту?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Расскажите о самом сложном техническом решении в вашей практике: как выбирали, какие альтернативы отвергли и почему?', 'Структура ответа (STAR): ситуация — бизнес-контекст и ограничения (SLA, объём, команда); задача — какая проблема требовала решения; действие — варианты с трейд-оффами (минимум два-три, каждому: цена, риск, время до результата), критерии выбора (измеримые: latency, стоимость, поддерживаемость), само решение и его реализация по шагам; результат — измеримый итог (метрика до/после) и вынесенные уроки. Сильный ответ всегда содержит: явные альтернативы (показывает широту), аргументацию против своего варианта (честность о минусах принятого решения), цифры и проверку гипотез (спайк/POC перед внедрением), что бы сделали иначе. Слабый: «выбрали X, потому что он лучший» без сравнения, грандиозный рассказ без вашей личной роли, техно-название без контекста бизнеса. Подготовьте 2 истории: архитектурное решение (выбор брокера/БД/декомпозиция) и производственный инцидент с вашим расследованием. Репетируйте вслух на 3-4 минуты каждая: интервьюер слушает ход мышления, а не название технологии.', 'Какую альтернативу вы отвергли и какие у неё были плюсы? Как измерили, что решение сработало? Что бы сделали иначе сегодня?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Конфликт в команде по технического решению: как вы действовали, когда команда не согласна с вашим подходом?', 'Хороший ответ демонстрирует зрелость: (1) сначала слушаю — opposing view формулирую так, чтобы оппонент согласился с формулировкой (steel man, не caricate); (2) перевожу спор из вкуса в критерии: что оптимизируем (latency? поддерживаемость? сроки?) и как это измерим; (3) ищу дешёвый эксперимент вместо теоретической дискуссии — спайк на день, бенчмарк, ADR с protoтипом; (4) если критерии не разрешают однозначно — решение принимает владелец домена, и я честно поддерживаю чужой вариант, если он выбран (disagree and commit), не саботирую; (5) фиксирую решение в ADR: контекст, варианты, что отвергли и почему — снимает повторные споры. Антипаттерны: «я senior, поэтому так», тишина на встрече и саботаж в код-ревью, эскалация наверх без попытки договориться. Пример-скелет: спор о Mongo vs PostgreSQL для новой фичи — сформулировал критерии (транзакционность, команда знакома, ops-поддержка), предложил спайк на реальных данных, по итогам выбрали вариант коллеги, зафиксировали ADR. Результат: фича в срок, отношения целы, процесс спора стал шаблоном для команды.', 'Бывали ли случаи, когда вы сознательно поддержали решение, с которым были не согласны? Как вы фиксируете архитектурные решения? Что делаете, если конфликт повторяется с тем же человеком?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Records и sealed types: что дают вместе и как меняют моделирование домена?', 'record — прозрачный носитель данных: final-поля, canonical-конструктор, equals/hashCode/toString генерируются; компактный конструктор валидирует инварианты (валидация на границе создания -> домен всегда корректен), нельзя наследоваться, компоненты можно аннотировать. Идеален для DTO, value-объектов, ключей мапы (корректный hashCode бесплатно). Sealed interface/class — закрытая иерархия: permits перечисляет допустимых наследников, все они final/sealed/non-sealed. Вместе они дают алгебраические типы: sealed interface Payment permits Card, Cash, Crypto + record на каждую ветку; компилятор знает все варианты -> exhaustive switch без default: при добавлении ветки компилятор сломает все неполные switch — рефакторинг безопасен. Pattern matching: switch по sealed-типу с деструктуризацией case Card(int pan, ...) -> полиморфизм без визитёра для простых случаев. Ограничения: record — shallow immutability (вложенные mutable коллекции надо копировать), sealed не работает с анонимными классами, рефлексия/фреймворки должны поддерживать. Для JPA-сущностей record не годится (нужен no-arg constructor + прокси), но для границ API/команд — идеально.', 'Почему exhaustive switch без default — это безопасность рефакторинга? Чем compact constructor лучше статической фабрики с проверками? Почему record не подходит как JPA-сущность, но идеален как DTO?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Виртуальные потоки Java 21: как устроены, что они меняют в серверной разработке и где всё ещё нужны платформенные потоки?', 'Виртуальный поток — дешёвая (десятки байт стека против МБ) конструкция, монтируемая на carrier-поток (ForkJoinPool) только на время выполнения; при блокировке на I/O JVM размонтирует его (парковка без занятия carrier) — сотни тысяч конкурентных задач на десятках ядер. Программная модель прежняя: последовательный код, блокирующий стиль, но масштабирование как у async (Project Loom). Что меняет: servlet-стек/Tomcat с виртуальными потоками (spring.threads.virtual.enabled=true в Boot 3.2+) держит огромное число concurrent соединений без реактивных переписываний; JDBC-вызовы перестают быть узким местом потоков. Ограничения/грабли: (1) pinning — synchronized блок, внутри которого происходит паркинг, держит carrier (JDK 24 исправляет в основном; до того — ReentrantLock); (2) ThreadLocal тяжёл при миллионах потоков — вместо него scoped values; (3) пулы для CPU-bound остаются платформенными — виртуальные решают только concurrency-of-io, не параллелизм вычислений; (4) в контейнерах с CPU-квотой 2 ядра виртуальные потоки не ускорят CPU-обработку. Практический вывод: новые IO-bound сервисы — виртуальные потоки + обычный блокирующий код; реактивщина (WebFlux) остаётся для специфичных случаев (стриминг, composite non-IO), CPU-пулы — явные executors.', 'Что такое pinning виртуального потока и почему synchronized + I/O — проблема до JDK 24? Почему ThreadLocal заменяют ScopedValues? В каком случае WebFlux остаётся оправданным при наличии Loom?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Отказы и репликация Redis: sentinel vs cluster, что теряется при failover?', 'Redis Sentinel — HA для одноинстансовой топологии: sentinel-процессы (3+) мониторят master, при отказе выбирают нового (majority quorum) и переконфигурируют клиентов/реплики; клиент (Spring Lettuce с sentinel-конфигом) узнаёт новый master сам. Поддерживает только sharding-нет — всё в одном шарде, масштабирование вертикальное. Redis Cluster — шардирование по 16384 hash-slots + встроенный failover: ключи распределены по master''ам, у каждого реплики; клиент умный (MOVED/ASK redirect) и знает слоты. Ограничения cluster: multi-key операции только в одном слоте (hash-tag {user:1}:... чтобы ключи попали вместе), транзакции/ Lua по нескольким слотам не работают, db SELECT нет (одна db 0). Failover-потери: асинхронная репликация — неподтверждённые записи последнего момента теряются (min-replicas-to-write смягчает); отказ sentinel-эпохи — split-brain возможен при сетевом разделе (кворум защищает). Персистентность: RDB (снапшот, потери между снапшотами) и AOF (fsync everysec — до секунды потерь); для кэша терпимо, для rate limiter/очередей — решение по бизнесу. Практика: cache — sentinel + AOF опционально; большие объёмы — cluster; гонки при failover лечит версионирование/идемпотентные записи на стороне приложения.', 'Чем MOVED отличается от ASK при редиректе в cluster? Почему multi-key команды требуют одного hash-slot и как помогают hash-теги? Что теряется при асинхронной репликации и что ограничивает потери?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Contract testing (Spring Cloud Contract) против интеграционных тестов в микросервисах: когда что оправдано?', 'Проблема межсервисных тестов: полный интеграционный стенд хрупок и медленный, а юнит-тесты не ловят несовместимость контракта. Consumer-driven contract testing: потребитель описывает ожидания (запрос -> ответ) как тест, провайдер верифицирует против них; Spring Cloud Contract: провайдер пишет контракты (Groovy/YAML), плагин генерирует тесты провайдеру и stubs потребителю; потребитель в своих тестах поднимает WireMock со stub''ом — быстрые юнит-скоростные тесты против реального контракта; при изменении API у провайдера падает верификация, у потребителя — его тесты против старого stub''а: несовместимость ловится в CI обоих репозиториев до деплоя. Pact — альтернатива с брокером контрактов (можно can-i-deploy проверку). Когда оправдано: много сервисов, частые релизы, команды раздельно; E2E-стенд оставляем для критического smoke (5-10 сценариев), контрактные тесты покрывают совместимость шин. Гранница с интеграционными: контракт проверяет форму (схему/статусы/семантику полей), интеграционный — поведение с реальной БД/брокером. В монорепозитории с одним деплоем контракты избыточны — хватит общих интеграционных тестов.', 'Как consumer-driven отличается от provider-driven контрактов? Что проверяет контрактный тест, а что не может? Как can-i-deploy в Pact предотвращает несовместимый деплой?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Replica set и согласованность в MongoDB: writeConcern, readPreference — как настроить под требования?', 'Replica set — один primary (принимает записи) + secondaries (реплицируют oplog); автоматический failover через election (требует majority живых voting-членов). writeConcern регулирует подтверждение записи: w:1 (только primary — быстро, потеря при сбое до репликации), w:majority (записана majority — переживёт failover, база для транзакций/ changestreams консистентности), j:true — journal на диске; задержка против durability. readPreference: primary (дефолт, read-your-writes), primaryPreferred, secondary (снимает нагрузку с primary, читаем possibly-stale), secondaryPreferred, nearest; maxStalenessSeconds ограничивает отставание. Causal consistency — сессия с causalConsistency + afterClusterTime даёт read-your-own-writes на вторичных. Транзакции требуют w:majority. Практика: финансовые записи — w:majority + j:true; аналитические чтения — secondary с maxStaleness; кэши — w:1. Изменение потока (change streams) требует replica set (даже одноузлового для dev). Oplog — capped-коллекция, окно репликации ограничено: вторичная, отставшая больше окна, требует initial sync.', 'Чем w:1 отличается от w:majority по сценариям потери данных при failover? Когда оправдан readPreference=secondary и что ломает read-your-writes? Почему change streams требуют replica set?' from categories where slug = 'mongodb';
